import collections
def back(target, tmax, depth, gap=600, seen=None):
    # backward reach set: nodes that could have influenced target by tmax
    res={target:tmax}
    frontier=[(target,tmax)]
    for _ in range(depth):
        new=[]
        for node,tt in frontier:
            for u,v,t in w:
                if v==node and t<tt and tt-t<=gap:
                    if u not in res or t>res.get(u,-1):
                        res[u]=t; new.append((u,t))
        frontier=new
        if not frontier: break
    return res
